/**
 * Generate the llms.txt files of the website.
 *
 * `llms.txt` is the index that tells an assistant which pages to read, and
 * `llms-full.txt` holds the whole content in one file. Both are generated from
 * the pages of the site, so they never go out of date.
 *
 * It runs after the build: the API reference is generated by the build itself.
 */
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const docsDir = path.join(root, "src", "content", "docs");

// The files are written where the build puts them: the script runs after the
// build, so the public directory has already been copied to the output.
const distDir = path.join(root, "dist");
const outDir = (await readdir(distDir).then(() => distDir).catch(() => path.join(root, "public")));

const SITE = "https://carlylekatto.github.io/distube-website";

/**
 * The pages of the site, in the order they should be read.
 */
const PAGES = [
  { file: "index.mdx", title: "DisTube", description: "The landing page: what the library does." },
  { file: "getting-started/installation.md", title: "Installation", description: "The requirements and the installation." },
  { file: "getting-started/quick-start.mdx", title: "Quick start", description: "Build a music bot with DisTube." },
  { file: "guide/events.md", title: "Handling events", description: "Every event of the library." },
  { file: "guide/plugins.md", title: "Plugin system", description: "The music sources, and how to write one." },
  { file: "guide/filters.md", title: "Audio filters", description: "The built-in filters, and the custom ones." },
  { file: "guide/discord-events.md", title: "Discord.js events", description: "The discord.js events a music bot needs." },
  { file: "guide/youtube-cookies.md", title: "YouTube cookies", description: "Why a source needs cookies, and how to give them." },
  { file: "guide/upgrade.md", title: "Upgrading", description: "What changed between the major versions." },
  { file: "faq.md", title: "FAQ", description: "The questions that come up the most." },
  { file: "projects.md", title: "Plugins & bots", description: "The official plugins, the community ones, and the bots." },
];

/**
 * The url of a page.
 */
const urlOf = (file) => {
  const clean = file.replace(/(index)?\.(md|mdx)$/u, "").replace(/\/$/u, "");
  return clean ? `${SITE}/${clean}/` : `${SITE}/`;
};

/**
 * Read the frontmatter and the body of a page.
 */
async function readPage(file) {
  const content = await readFile(path.join(docsDir, file), "utf8");
  const match = /^---\r?\n([\s\S]*?)\r?\n---/u.exec(content);
  const frontmatter = match?.[1] ?? "";
  const title = /^title:\s*(.+)$/mu.exec(frontmatter)?.[1]?.trim() ?? "";
  const description = /^description:\s*(.+)$/mu.exec(frontmatter)?.[1]?.trim() ?? "";
  const body = content.slice(match ? match[0].length : 0);
  return { title, description, body };
}

/**
 * The pages of the generated API reference.
 */
async function readApiPages() {
  const apiDir = path.join(docsDir, "api");
  const pages = [];
  const walk = async (dir, prefix) => {
    let entries;
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        await walk(full, `${prefix}${entry.name}/`);
        continue;
      }
      if (!entry.name.endsWith(".md")) continue;
      const slug = entry.name.replace(/\.md$/u, "").replace(/^readme$/u, "index");
      const content = await readFile(full, "utf8");
      const title = /^#\s+(.+)$/mu.exec(content)?.[1]?.trim() ?? slug;
      pages.push({
        file: `api/${prefix}${slug}.md`,
        title,
        description: `The reference of ${title}.`,
        body: content,
        url: `${SITE}/api/${prefix}${slug === "index" ? "" : `${slug}/`}`,
      });
    }
  };
  await walk(apiDir, "");
  return pages;
}

const index = [
  "# DisTube",
  "",
  "> A powerful Discord.js module for simplifying music commands and effortless playback of various sources with integrated audio filters.",
  "",
  "The documentation of DisTube, the Discord music library for discord.js.",
  "",
];

const full = ["# DisTube", "", "The full documentation of DisTube, in one file.", ""];

for (const page of PAGES) {
  let parsed;
  try {
    parsed = await readPage(page.file);
  } catch {
    console.warn(`skipped ${page.file}`);
    continue;
  }

  const title = parsed.title || page.title;
  const description = parsed.description || page.description;

  index.push(`## [${title}](${urlOf(page.file)})`, "", description, "");
  full.push("---", "", `# ${title}`, "", `Source: ${urlOf(page.file)}`, "", parsed.body.trim(), "");
}

const apiPages = await readApiPages();
if (apiPages.length) {
  index.push("## The API reference", "", "Every exported class, interface, type and function of the library.", "");
  for (const page of apiPages) {
    index.push(`- [${page.title}](${page.url})`);
  }
  index.push("");
  for (const page of apiPages) {
    full.push("---", "", `# ${page.title}`, "", `Source: ${page.url}`, "", page.body.trim(), "");
  }
} else {
  console.warn("the API reference is empty");
}

index.push(
  "## Optional",
  "",
  "- [The repository of the library](https://github.com/carlylekatto/DisTube)",
  "- [The Discord server](https://discord.gg/feaDd9h)",
  "",
);

await writeFile(path.join(outDir, "llms.txt"), index.join("\n"), "utf8");
await writeFile(path.join(outDir, "llms-full.txt"), full.join("\n"), "utf8");

console.log(`llms.txt: ${index.length} lines`);
console.log(`llms-full.txt: ${full.join("\n").length} characters`);
console.log(`api pages: ${apiPages.length}`);
